# owner: platform
from typing import List
from hourglass.models import Shift
from collections import defaultdict

def check_shifts(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")

def tally(shifts: List[Shift]) -> dict:
    totals = defaultdict(lambda: [0, 0])
    for shift in shifts:
        entry = totals[shift.worker]
        entry[0] += 1
        entry[1] += shift.span.minutes
    return totals

def format_row(name: str, entry: list) -> str:
    hours = entry[1] / 60
    return f"{name}: {entry[0]} shifts, {hours:.1f} hours"

def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    check_shifts(shifts)
    rows = sorted(
        tally(shifts).items(),
        key=lambda item: (-item[1][1], item[0])
    )
    return [format_row(name, entry) for name, entry in rows]
